INSERT INTO grammar_lessons (id, grammar_chapter_id, title, pattern, meaning_vi, explanation, formation, jlpt_level_id, display_order, is_published, version) VALUES
(120, 26, '～んです', 'V 普通形 / A い ＋ い', '～んです', '(thể thường)', '1. ～んです / 2. ～んですか / 3. V ていただけませんか', 2, 1, TRUE, 1),
(121, 26, '～んです', '～んですか', '～んです', 'Ly hôm nay vui nhỉ. Bạn có người yêu à? ❖ Người nói muốn được cung cấp thêm thông tin về những gì mình đã nhìn hoặc nghe thấy.', '2. ～んです / ～んですか / ひまじゃ', 2, 2, TRUE, 1),
(122, 26, 'V ていただけませんか', '～V ていただけませんか / ❖ So với V てください thì cách nói này lịch sự hơn.', 'V ていただけませんか', 'Bạn copy tài liệu đó giúp tôi được không?', '3. V ていただけませんか / ～V ていただけませんか / ❖ So với V てください thì cách nói này lịch sự hơn.', 2, 3, TRUE, 1),
(123, 26, '～んですが', '～んですが、～ / ❖ が: dùng để nối các vế câu lại với nhau biểu hiện', '～んですが', 'Câu hỏi này tôi vẫn chưa hiểu. Bạn chỉ cho tôi thêm 1 lần nữa được không?', '4. ～んですが / ～んですが、～ / ❖ が: dùng để nối các vế câu lại với nhau biểu hiện', 2, 4, TRUE, 1),
(124, 26, '疑問詞＋V たらいいですか (từ để hỏi)', '疑問詞＋V たらいいですか (từ để hỏi)', '疑問詞＋V たらいいですか (từ để hỏi)', '❖ Dùng khi muốn nghe sự khuyên bảo, hướng dẫn mình nên làm gì. ❖ Từ để hỏi:', '5. 疑問詞＋V たらいいですか (từ để hỏi) / Q: Từ để hỏi ＋ V たらいいですか。 / A: V たら いいです。', 2, 5, TRUE, 1),
(125, 26, 'N (tân ngữ) はすきです', 'N (tân ngữ) はすきです', 'N (tân ngữ) はすきです', 'Tarou ơi, ăn rau đi con. Không, con ghét rau.', '6. N (tân ngữ) はすきです / すきです／きらいです。 / N (tân ngữ) は じょうずです／へたです。', 2, 6, TRUE, 1),
(126, 27, '可能形 (かのうけい)', 'Hàng い(i) / ～(i)ます→～(e)ます', '可能形 (かのうけい)', 'Cách dùng thể khả năng: ❖ Chú ý :', '1. 可能形 (かのうけい) / 2. 見えます・聞こえます / 3. 場所に N ができます', 2, 1, TRUE, 1),
(127, 27, '見えます・聞こえます', '❖ 見 / み', '見えます・聞こえます', 'Từ đây có thể nhìn thấy biển. CHỦ QUAN KHÁCH QUAN PHÂN BIỆT Đeo kính thì nhìn thấy chữ.', '2. 見えます・聞こえます / ❖ 見 / み', 2, 2, TRUE, 1),
(128, 27, '場所 (địa điểm) にN が できます', 'Địa điểm に N が できます', '場所 (địa điểm) にN が できます', 'Trước nhà ga có siêu thị đã được xây xong.', '3. 場所 (địa điểm) にN が できます / Địa điểm に N が できます', 2, 3, TRUE, 1),
(129, 27, 'N(lượng từ)しかＶません', '❖ Ý Nghĩa: Chỉ ~ / ❖ Dù đuôi là ません nhưng là câu khẳng định', 'N(lượng từ)しかＶません', 'Tôi chỉ nói được tiếng Nhật.', '4. N(lượng từ)しかＶません / ❖ Ý Nghĩa: Chỉ ~ / ❖ Dù đuôi là ません nhưng là câu khẳng định', 2, 4, TRUE, 1),
(130, 27, 'N1 は～が、N2 は～', 'N1 は～が、N2 は～ / ❖ Ý Nghĩa: So sánh đối lập 2 vế của câu', 'N1 は～が、N2 は～', 'Tôi thì có thể viết Hiragana nhưng, kanji thì không thể viết.', '5. N1 は～が、N2 は～ / N1 は～が、N2 は～ / ❖ Ý Nghĩa: So sánh đối lập 2 vế của câu', 2, 5, TRUE, 1),
(131, 28, 'ながら', 'ながら', 'ながら', 'Bố tôi vừa uống bia vừa làm việc. Maria vừa đi làm vừa học đại học. ❖ Với các động từ khoảnh khắc (thức dậy, mặc, đội mũ, ❖ Với các động từ di chuyển thì sẽ đặt ở vế sau nhắm vào hành động nào thì hành động đó nằm ở vế sau kết hợp với các dạng này.', '1. ながら / 2. V ています / 3. ～し、～し、それに', 2, 1, TRUE, 1),
(132, 28, 'V ています', 'V ています / ❖ Nếu diễn tả thói quen trong quá khứ thì dung:', 'V ています', 'Ngày nghỉ tôi thường chơi tennis với bạn bè.', '2. V ています / V ています / ❖ Nếu diễn tả thói quen trong quá khứ thì dung:', 2, 2, TRUE, 1),
(133, 28, '～し、～し、それに', '❖ Trợ từ が được chuyển thành も để nhấn mạnh quan điểm. / ❖ それに：hơn nữa, thêm vào đó', '～し、～し、それに', 'Hà Nội vừa náo nhiệt, vừa có phong cảnh đẹp, Hơn nữa lại có nhiều đồ ăn ngon.', '3. ～し、～し、それに / ❖ Trợ từ が được chuyển thành も để nhấn mạnh quan điểm. / ❖ それに：hơn nữa, thêm vào đó', 2, 3, TRUE, 1),
(134, 28, '～し、～し、（それで）', '❖ Ở mẫu câu này phần ～し、～し được dùng để trình bày lý / ❖ それで： vì vậy, vì thế', '～し、～し、（それで）', 'Công việc vừa thú vị, lương cao, vì vậy tôi muốn làm việc ở công ty này.', '4. ～し、～し、（それで） / ❖ Ở mẫu câu này phần ～し、～し được dùng để trình bày lý / ❖ それで： vì vậy, vì thế', 2, 4, TRUE, 1),
(135, 28, '～し、～ から', '＋ し 、～し、（それで）～ / V（普通形）(thể thông thường)', '～し、～ から', 'trình bày lý do cho phần nội dung nói đến phía sau đó. nguyên nhân – lý do, dẫn đến kết quả – kết luận ở', '5. ～し、～ から / ＋ し 、～し、（それで）～ / V（普通形）(thể thông thường)', 2, 5, TRUE, 1),
(136, 29, '(もう／ぜんぶ) +', 'V てしまいます', '(もう／ぜんぶ) +', 'Mẫu ngữ pháp N4: (もう／ぜんぶ) +.', '1.(もう／ぜんぶ) + / V てしまいます', 2, 1, TRUE, 1),
(137, 29, '(もう／ぜんぶ) +', '(もう／ぜんぶ) +', '(もう／ぜんぶ) +', 'Tôi sẽ lau xong toàn bộ bàn của cửa hàng. ❖ Diễn tả hối hận, tiếc nuối về một việc đã xảy ra (chỉ dùng dạng quá khứ)', '２.(もう／ぜんぶ) + / みせ / の机', 2, 2, TRUE, 1),
(138, 29, '(もう／ぜんぶ) +', '(もう／ぜんぶ) +', '(もう／ぜんぶ) +', 'Mẫu ngữ pháp N4: (もう／ぜんぶ) +.', '(もう／ぜんぶ) +', 2, 3, TRUE, 1),
(139, 29, 'N(nơi chốn) に行きます／来ます／帰ります', 'N(nơi chốn) に行きます／来ます／帰ります / Những động từ như 行きます／来ます／帰ります', 'N(nơi chốn) に行きます／来ます／帰ります', 'Phân biệt triệt để toàn bộ 100% hay chưa. VD:', '4. N(nơi chốn) に行きます／来ます／帰ります / N(nơi chốn) に行きます／来ます／帰ります / Những động từ như 行きます／来ます／帰ります', 2, 4, TRUE, 1),
(140, 29, 'それ／その／そう', 'それ／その／そう', 'それ／その／そう', 'Từ tháng sau, tôi sẽ chuyển việc về công ty mẹ ở Osaka Xin chúc mừng anh/chị về điều đó Đi đến nhà ga Đến trường Trở về nhà', '5. それ／その／そう / A: 来月 / らいげつ', 2, 5, TRUE, 1),
(141, 29, 'ありました', '❖ Trong câu trên ［かばんが］ biểu thị rằng người', 'ありました', 'Lấy cho tôi tài liệu ở trên bàn. Vâng, nó không có ở đây. A, nó ở bên cạnh cái máy tính.', '6. ありました / ❖ Trong câu trên ［かばんが］ biểu thị rằng người / A: 机', 2, 6, TRUE, 1),
(142, 29, 'どこかで／どこかに', '❖ どこかで ：Diễn tả nơi diễn ra , xảy ra hành động', 'どこかで／どこかに', 'Tôi lỡ đánh rơi mất ví ở đâu đó rồi.', '7. どこかで／どこかに / ❖ どこかで ：Diễn tả nơi diễn ra , xảy ra hành động / さいふ', 2, 7, TRUE, 1),
(143, 30, 'Chuẩn bị', 'Chuẩn bị', 'Chuẩn bị', 'Mẫu ngữ pháp N4: Chuẩn bị.', 'Chuẩn bị', 2, 1, TRUE, 1),
(144, 30, 'Thực hiện hành động ĐỂ LẦN SAU CÒN DÙNG LẠI,', 'hoặc ĐƯA VỀ TRẠNG THÁI BAN ĐẦU (rửa bát, để', 'Thực hiện hành động ĐỂ LẦN SAU CÒN DÙNG LẠI,', 'Trước giờ học, tôi chuẩn bị trước bài mới. Ví dụ V Tự động từ Tha động từ Ý nghĩa Chỉ diễn tả trạng thái của cửa sổ đang đóng. Diễn tả trạng thái cửa sổ đóng là kết quả có chủ ý của 1 ai đó. Sau khi ăn cơm xong, tôi rửa bát. Tôi tắt điều hòa nhé? Trời nóng nên bạn cứ bật điều hòa như thế nhé.', '2. Thực hiện hành động ĐỂ LẦN SAU CÒN DÙNG LẠI, / hoặc ĐƯA VỀ TRẠNG THÁI BAN ĐẦU (rửa bát, để / 授業', 2, 2, TRUE, 1),
(145, 30, 'また', 'また', 'また', 'Trời vẫn còn đang mưa. ❖ Ý nghĩa : Vẫn chưa…( Diễn tả trạng thái hành động đang diễn ra và chưa xong)', '3. また / あめ / が まだ ふっています。', 2, 3, TRUE, 1),
(146, 30, 'とか', '「とか」và「や」đều được dùng khi liệt kê ví dụ.', 'とか', 'B: À vâng, tôi chơi mấy môn như là quần vợt, bơi lội,... Kết hợp với N Kết hợp với V × Trường hợp sử dụng Văn viết Văn nói', '4. とか / 「とか」và「や」đều được dùng khi liệt kê ví dụ. / A: Anh thường chơi môn thể thao gì?', 2, 4, TRUE, 1),
(147, 30, '格助詞(trợ từ cách) + も', 'Trợ từ も khi kết hợp với danh từ có các trợ từ「が」, / 「を」đi kèm thì các trợ từ 「が」,「を」 sẽ được', '格助詞(trợ từ cách) + も', 'Ngày nghỉ tôi chẳng đi đâu cả.', '5. 格助詞(trợ từ cách) + も / Trợ từ も khi kết hợp với danh từ có các trợ từ「が」, / 「を」đi kèm thì các trợ từ 「が」,「を」 sẽ được', 2, 5, TRUE, 1),
(148, 31, '意向形', 'あいます / あおう', '意向形', 'Nhóm I Nhóm II V D:', '1. 意向形 / 2. ～と思っています / 3. まだ～V ていません', 2, 1, TRUE, 1),
(149, 31, '～ (よう）と思', 'おも / っています', '～ (よう）と思', 'Tôi đang định đi xem phim vào tuần sau.', '2. ～ (よう）と思 / おも / っています', 2, 2, TRUE, 1),
(150, 31, 'まだ～V ていません', '(終わっていません、できていません）', 'まだ～V ていません', 'Tôi vẫn chưa tìm thấy cái túi xách màu trắng của mẹ tôi.', '3. まだ～V ていません / (終わっていません、できていません） / はは', 2, 3, TRUE, 1),
(151, 31, '～つもりです', '❖ 「V るつもりです」: diễn đạt ý định làm 1 việc gì đó / ＋ つもりです', '～つもりです', 'Tôi sẽ không chơi game từ thứ 2 đến thứ 6.', '4. ～つもりです / ❖ 「V るつもりです」: diễn đạt ý định làm 1 việc gì đó / ＋ つもりです', 2, 4, TRUE, 1),
(152, 31, '～予定', 'よてい / です', '～予定', 'Tháng 1 năm sau tôi kế hoạch sẽ kết hôn với người yêu.', '5. ～予定 / よてい / です', 2, 5, TRUE, 1),
(153, 32, 'V た・Ｖない ほうがいいです', 'S は / ほうがいいです', 'V た・Ｖない ほうがいいです', 'Mẫu ngữ pháp N4: V た・Ｖない ほうがいいです.', '1. V た・Ｖない ほうがいいです / 2. ～でしょう / 3. ～かもしれません', 2, 1, TRUE, 1),
(154, 32, '～でしょう', '～でしょう', '～でしょう', 'Cuối tuần có lẽ bão sẽ đến.', '2. ～でしょう / きっと、たぶん、。。。 / しゅうまつ', 2, 2, TRUE, 1),
(155, 32, '～かも しれません', 'V（普通形） / A な/N（普通形）だ', '～かも しれません', 'Lạnh thế nhỉ. Chắc là tối nay tuyết sẽ rơi.', '3. ～かも しれません / V（普通形） / A い（普通形） でしょう。', 2, 3, TRUE, 1),
(156, 32, 'Lượng từ + で', 'Lượng từ + で', 'Lượng từ + で', '15 man yên có đi du lịch Nhật Bản được không?', '4. Lượng từ + で / 15万円 / まんえん', 2, 4, TRUE, 1),
(157, 32, 'Từ để hỏi + か', '何 / なん', 'Từ để hỏi + か', 'VD: Q: Chị có điều gì lo lắng à? A: Tôi đang lo lắng cho sức khỏe của mẹ.', '5. Từ để hỏi + か / 何 / なん', 2, 5, TRUE, 1),
(158, 33, '命令形', 'めいれいけい / ・禁止形', '命令形', 'Thể mệnh lệnh Thể cấm chỉ hoạn, các biển báo giao thông, biển chú ý. CÁCH CHIA THỂ MỆNH LỆNH', '1. 命令形 / めいれいけい / ・禁止形', 2, 1, TRUE, 1),
(159, 33, '～と読', 'よ / みます ・～と書', '～と読', '❖ được đọc là~ ❖ được viết là~ VD:', '2. ～と読 / よ / みます ・～と書', 2, 2, TRUE, 1),
(160, 33, '～という意味', 'い / み', '～という意味', 'Kí hiệu này nghĩa là cấm sử dụng.', '3. ～という意味 / い / み', 2, 3, TRUE, 1),
(161, 33, '～と言', 'い / っていました', '～と言', 'Nam đã nói là bữa tiệc sẽ tổ chức vào 6 giờ.', '4. ～と言 / い / っていました', 2, 4, TRUE, 1),
(162, 33, '～と伝えて いただけませんか', '～と伝えて いただけませんか', '～と伝えて いただけませんか', 'Bà nhắn cho ông giúp cháu là ông nên tập thể dục nhiều được không ạ?', '5. ～と伝えて いただけませんか / おじいさんに よく運動 / うんどう', 2, 5, TRUE, 1),
(163, 34, 'V る・V た・N の ＋とおりに、 V2', 'とおりに、 V2 / V1 る', 'V る・V た・N の ＋とおりに、 V2', 'Sau đây, các bạn hãy cùng nói theo những gì tôi nói. Lưu ý: ❖ Diễn tả hành động V2 bắt chước sau khi V1 đã thực hiện xong xuôi.', '1. V る・V た・N の ＋とおりに、 V2 / 2. V た・N の ＋あとで、 V2 / 3. V１て・V１ないで ＋ V２', 2, 1, TRUE, 1),
(164, 34, 'V た/の＋あとで、 V2', '❖ V2 được thực hiện sau khi V1, N diễn ra hoặc thực hiện / V1 たとおりに、V2', 'V た/の＋あとで、 V2', 'Tôi tắm sau khi chơi bóng đá xong. ❖ Cả hai mẫu câu đều nhấn mạnh trình tự thời gian (làm V1 rồi làm V2 rồi mới làm V3).', '2. V た/の＋あとで、 V2 / ❖ V2 được thực hiện sau khi V1, N diễn ra hoặc thực hiện / V1 たとおりに、V2', 2, 2, TRUE, 1),
(165, 34, '～という意味', 'い / み', '～という意味', 'Lái xe có thắt dây an toàn. Lái xe không thắt dây an toàn. Lưu ý: ❖ V1, V2: Lựa chọn hành động V2 thay vì thực hiện hành động V1.', '3. ～という意味 / い / み', 2, 3, TRUE, 1),
