(213, 45, 'のに、～', '「V る場合」: trong TH trước khi xảy ra ∼, cần làm gì / 「V た場合」: trong TH đã xảy ra ∼, cần làm gì ∼', 'のに、～', 'Đã có hẹn rồi thế mà cô ấy không đến. Điện thoại này đắt vậy mà rất hay hỏng hóc.', '2. のに、～ / 「V る場合」: trong TH trước khi xảy ra ∼, cần làm gì / 「V た場合」: trong TH đã xảy ra ∼, cần làm gì ∼', 2, 2, TRUE, 1),
(214, 46, '～ところ', '❖ Thường đi kèm với: たった今', '～ところ', 'Tôi vừa mới ăn cơm xong.', '1. ～ところ / 2. ～ばかり / 3. ～はず', 2, 1, TRUE, 1),
(215, 46, '～ばかり', '• V たところです： Sự việc vừa xảy ra và / • V たばかりです：Thời điểm xảy ra sự việc', '～ばかり', 'Chú ý: vừa mới kết thúc, thời điểm xảy ra sự việc ngắn. ngắn hay dài tùy vào cảm nhận của người nói.', '2. ～ばかり / • V たところです： Sự việc vừa xảy ra và / • V たばかりです：Thời điểm xảy ra sự việc', 2, 2, TRUE, 1),
(216, 46, '～はず', '～はず', '～はず', 'Tối nay chắc chắn sẽ mưa. Vì sáng nay tôi đã xem dự báo thời tiết.', '3. ～はず / 今晩 / こんばん', 2, 3, TRUE, 1),
(217, 47, '～そうです', '(N によると）普通形 + そうです / PHÂN BIỆT', '～そうです', 'PHÂN BIỆT Cách kết hợp', '1. ～そうです / 2. ～ようです / 3. ～N がします', 2, 1, TRUE, 1),
(218, 47, '～ようです', '～ようです', '～ようです', 'Hình như Nam thích sách. Lúc nào cũng thấy đang cầm quyển sách. Hình như em bé không thích sữa này.', '2. ～ようです / ナムさんは 本 / ほん', 2, 2, TRUE, 1),
(219, 47, '～N がします', '～N がします', '～N がします', 'Có tiếng ồn ào nhỉ.', '3. ～N がします / にぎやかな声 / こえ', 2, 3, TRUE, 1),
(220, 48, '使役形', 'しえきかたち / しえきけい', '使役形', 'Cách dùng: ❖ Sai khiến, cho phép (không dùng với người trên). Chú ý: V sau khi chia về thể sai khiến được coi như V nhóm 2.', '1. 使役形 / しえきかたち / 2. N をV（使役形', 2, 1, TRUE, 1),
(221, 48, 'N をV（使役形', 'しえきけい / ❖ A sai/ bắt/ phân công/ để/ cho B làm V.', 'N をV（使役形', 'Chú ý: ❖ Cấu trúc này cũng có ý nghĩa: A làm cho/khiến B cảm thấy V (tâm trạng, cảm xúc)', '2. N をV（使役形 / しえきけい / ❖ A sai/ bắt/ phân công/ để/ cho B làm V.', 2, 2, TRUE, 1),
(222, 48, 'N１にN2 をV（使役形', 'しえきけい / ❖ A sai, bắt, phân công, để, cho B làm N.', 'N１にN2 をV（使役形', 'Khi còn nhỏ, mẹ tôi bắt tôi ăn nhiều rau. Tôi muốn cho con gái học piano. Chú ý: ❖ Trường hợp muốn nhận sự giúp đỡ từ người trên thì ❖ Trường hợp muốn nhận sự giúp đỡ từ người ngang bằng hoặc người dưới thì dùng mẫu Người bị sai khiến Người sai khiến Nội động từ Người bị sai khiến', '3. N１にN2 をV（使役形 / しえきけい / ❖ A sai, bắt, phân công, để, cho B làm N.', 2, 3, TRUE, 1),
(223, 48, 'V させてていただけませんか', '「～てもいいですか。」.', 'V させてていただけませんか', 'Cho phép tôi ghi âm cuộc họp có được không ạ? ❖ Để xin phép mà không cần sự đồng ý của đối phương ta dùng mẫu câu:', '4. V させてていただけませんか / 「～てもいいですか。」. / 会議', 2, 4, TRUE, 1),
(224, 49, 'Đối với các động từ có cách nói tôn kính đặc biệt', 'thì không dùng hình thức thể bị động và mẫu「お / ～になります」mà sử dụng dạng đặc biệt của', 'Đối với các động từ có cách nói tôn kính đặc biệt', 'động từ đó.', 'thì không dùng hình thức thể bị động và mẫu「お / ～になります」mà sử dụng dạng đặc biệt của', 2, 1, TRUE, 1),
(225, 49, 'Không sử dụng 2 tầng kính ngữ trong 1 từ', 'Không sử dụng 2 tầng kính ngữ trong 1 từ', 'Không sử dụng 2 tầng kính ngữ trong 1 từ', 'Mẫu ngữ pháp N4: Không sử dụng 2 tầng kính ngữ trong 1 từ.', 'Không sử dụng 2 tầng kính ngữ trong 1 từ', 2, 2, TRUE, 1),
(226, 49, 'お～になります', '❖ Có mức độ lịch sự cao hơn 「V られます」. / ❖ Không dùng với V đứng trước ます có 1 âm tiết như い', 'お～になります', 'Chú ý: ❖ Không dùng cho V nhóm 3', '3. お～になります / ❖ Có mức độ lịch sự cao hơn 「V られます」. / ❖ Không dùng với V đứng trước ます có 1 âm tiết như い', 2, 3, TRUE, 1),
(227, 49, '特別', 'とくべつ / な尊敬語', '特別', 'Chú ý: 1. Đối với các động từ có cách nói tôn kính đặc biệt động từ đó.', '4. 特別 / とくべつ / な尊敬語', 2, 4, TRUE, 1),
(228, 49, 'お/ご～ください', '➢ 召し上がります / ➢ ごらんになります', 'お/ご～ください', 'Chú ý: ❖ Không dùng cấu trúc này với các kính ngữ đặc biệt, trừ 2 động từ.', '5. お/ご～ください / ➢ 召し上がります / ➢ ごらんになります', 2, 5, TRUE, 1),
(229, 49, 'お/ご～ですか', '申 / もう', 'お/ご～ですか', 'Anh chị đăng kí không ạ? Quý khách có mang theo thẻ thư viện không ạ?', '6. お/ご～ですか / 申 / もう', 2, 6, TRUE, 1),
(230, 50, '謙譲語', 'けんじょうご / V(I,II)', '謙譲語', 'Tôi sẽ thông báo thời gian cuộc họp cho giám đốc.', '1. 謙譲語 / けんじょうご / V(I,II)', 2, 1, TRUE, 1),
(231, 50, '謙譲語', 'けんじょうご / V(III)', '謙譲語', 'Sau đây tôi xin phép giới thiệu về Tokyo ạ.', '2. 謙譲語 / けんじょうご / V(III)', 2, 2, TRUE, 1),
(232, 50, '謙譲語', 'けんじょうご / の特別', '謙譲語', 'Tôi sẽ đến vào 9 giờ sáng mai. Tôi biết anh/chị bận nhưng nếu có thời gian rảnh thì mời anh chị đến nhà tôi chơi.', '3. 謙譲語 / けんじょうご / の特別', 2, 3, TRUE, 1)
INSERT INTO grammar_examples (id, grammar_lesson_id, japanese_text, reading, meaning_vi, display_order) VALUES
(154, 120, '日本語を勉強します。', NULL, 'Ví dụ minh họa cho mẫu: ～んです.', 1),
