(178, 140, 'なんです。', NULL, 'Từ tháng sau, tôi sẽ chuyển việc về công ty mẹ ở Osaka', 1),
(179, 140, 'B: それ おめでとうございます。', NULL, 'Xin chúc mừng anh/chị về điều đó Đi đến nhà ga Đến trường Trở về nhà', 2),
(180, 141, 'をもってください。', NULL, 'Lấy cho tôi tài liệu ở trên bàn.', 1),
(181, 141, 'B: はい、へー、ありません。', NULL, 'Vâng, nó không có ở đây.', 2),
