(192, 149, 'っています。', NULL, 'Tôi đang định đi xem phim vào tuần sau.', 1),
(193, 150, 'つけていません。', NULL, 'Tôi vẫn chưa tìm thấy cái túi xách màu trắng của mẹ tôi.', 1),
(194, 151, 'つもりです。', NULL, 'Tôi sẽ không chơi game từ thứ 2 đến thứ 6.', 1),
