(205, 162, 'えていただけませんか。', NULL, 'Bà nhắn cho ông giúp cháu là ông nên tập thể dục nhiều được không ạ?', 1),
(206, 163, 'ってください。', NULL, 'Sau đây, các bạn hãy cùng nói theo những gì tôi nói. Lưu ý:', 1),
(207, 163, 'ってください。', NULL, 'Bạn hãy nói lại những gì tôi đã nói.', 2),
(208, 164, 'サッカーを したあとで、シャワーを あびます。', NULL, 'Tôi tắm sau khi chơi bóng đá xong.', 1),
(209, 164, 'きてから、はを みがきました。', NULL, 'Sáng nay sau khi thức dậy tôi đã đánh răng. thực hiện khi nào?”', 2),
(210, 165, '日本語を勉強します。', NULL, 'Ví dụ minh họa cho mẫu: ～という意味.', 1),
(211, 166, 'レーバーを ひけば、ドアが ひらきます。', NULL, 'Nếu kéo cần gạt thì cửa sẽ mở ra.', 1),
(212, 167, '彼が 行けば、私も行きます。', NULL, 'Nếu anh ấy đi thì tôi cũng đi. V1 + V2 PHÂN BIỆT Hễ mà ~ , cứ ~ thì sẽ ~ → diễn tả sự thật hiển nhiên, quy luật Sử dụng nói trong câu điều kiện : Nếu…..thì…..', 1),
(213, 168, 'すればいいですか。', NULL, 'Tỏ tình khi nào thì tốt nhỉ?', 1),
(214, 169, 'がいいですよ。', NULL, 'A: Tôi muốn đi Hokaido ấy... B: Nếu mà là Hokaido, thì tháng 6 đi ok đấy.', 1),
(215, 170, 'B: いいえ、ありません。', NULL, 'A: Anh có ý kiến gì khác không? B: Không, tôi không có.', 1),
(216, 171, '日本語を勉強します。', NULL, 'Ví dụ minh họa cho mẫu: V1 る・V1 ない ＋ように、V2.', 1),
(217, 172, 'べられる ようになりました。', NULL, 'Nếu kéo cần gạt thì cửa sẽ mở ra.', 1),
(218, 172, 'ジョギングをするようになりました。', NULL, 'Từ tháng trước tôi đã bắt đầu chạy bộ mỗi buổi sáng. ＊ Bạn đã có thể ~ chưa? Bạn đã có thể đọc được báo Nhật chưa?', 2),
(219, 173, 'ようにしています。', NULL, 'Vì có hại cho cơ thể nên tôi cố gắng không uống nhiều rượu.', 1),
(220, 174, '名前を書いてください。', NULL, 'Hãy viết tên.', 1),
(221, 175, 'きる ようにしています。', NULL, 'Mỗi sáng tôi cố gắng thức dậy sớm.', 1),
(222, 175, 'すみませんが、まどを開けてください。', NULL, '＋ V', 2),
(223, 176, '教室に学生がいます。', NULL, 'Trong lớp có học sinh.', 1),
(224, 177, 'に たのまれました。', NULL, 'Tôi đã bị trưởng phòng nhờ vả. ⮚ A là người BỊ hành động tác động vào. ⮚ B là người thực hiện hành động tác động vào N đồ sở hữu của A. ⮚ N là những thứ thuộc sở hữu của A (đồ vật, bộ phận cơ thể : chân, tay...vv)', 1),
(225, 177, '弟に おもちゃを こわされました。', NULL, 'Tôi bị em trai làm hỏng đồ chơi. (thể bị động) (thực hiện hành vi) (tiếp nhận hành vi)', 2),
(226, 178, 'せきゆは ふねで はこばれます。', NULL, 'Dầu mỏ được vận chuyển bằng thuyền.', 1),
(227, 179, 'られました。', NULL, 'Mì ăn liền được làm từ lúa mì.', 1),
(228, 180, '日本語を勉強します。', NULL, 'Ví dụ minh họa cho mẫu: Ⅴる/N ＋ の.', 1),
(229, 181, 'このかばんはいくらですか。', NULL, 'Cái cặp này giá bao nhiêu?', 1),
(230, 182, 'うのを 忘れました。', NULL, 'Tôi quên mua thịt rồi.', 1),
(231, 183, 'ていますか。', NULL, 'Bạn có biết anh Yamada đã nghỉ việc tuần trước rồi không?', 1),
(232, 183, 'Phân biệt 知りません và 知りませんでした', NULL, 'chưa nhận được thông tin từ câu hỏi.', 2),
(233, 184, '日本語を勉強します。', NULL, 'Ví dụ minh họa cho mẫu: V/A/N１ ＋のはN2 です.', 1),
(234, 185, '日本語を勉強します。', NULL, 'Ví dụ minh họa cho mẫu: V て/A いくて・A なで、～.', 1),
(235, 186, 'で、けがを してしまいました。', NULL, 'Vì tai nạn giao thông nên bị thương.', 1),
(236, 187, 'れました。', NULL, 'Vì xe bus đến muộn nên tôi đến trường muộn.', 1),
(237, 188, 'が かかりました。', NULL, 'Đang trong giờ học thì có điện thoại.', 1),
(238, 189, '日本語を勉強します。', NULL, 'Ví dụ minh họa cho mẫu: ～ か、～.', 1),
(239, 190, 'えていません。', NULL, 'Tôi không nhớ là trước khi đi ra ngoài đã tắt đèn hay chưa.', 1),
(240, 191, 'みたいです。', NULL, 'Tối nay em muốn ăn thử ở nhà hàng gần ga.', 1),
(241, 192, 'っていますか。', NULL, 'Bạn có biết người ta đo chiều dài của con sông này như thế nào không?', 1),
(242, 193, 'でどうでしょうか。', NULL, 'Cháu Minh và My ở trường như thế nào ạ?', 1),
(243, 194, 'して いただきます。', NULL, 'Tôi được trưởng phòng sửa cho lỗi sai trong báo cáo.', 1),
(244, 194, 'ってもらいます。', NULL, 'Tôi được anh trai mua cho xe máy mới.', 2),
(245, 195, 'くださいました。', NULL, 'Thầy Tanaka cho tôi tivi mới.', 1),
